function updateCompare(){const n=Number($('compare').value);$('before-layer').style.clipPath=`inset(0 ${100-n}% 0 0)`;$('compare-line').style.left=`${n}%`;}
function fitCropRatio(){if(!cropRatio||!cropDraft)return;const i=active(),w=Math.min(cropDraft.w,i.w-cropDraft.x,(i.h-cropDraft.y)*cropRatio);cropDraft.w=Math.max(1,Math.floor(w));cropDraft.h=Math.max(1,Math.round(cropDraft.w/cropRatio));}
function drawCrop(){if(!cropDraft||currentTool!=='crop')return;const i=active(),c=$('crop-box');c.style.left=`${cropDraft.x/i.w*100}%`;c.style.top=`${cropDraft.y/i.h*100}%`;c.style.width=`${cropDraft.w/i.w*100}%`;c.style.height=`${cropDraft.h/i.h*100}%`;$('crop-size').textContent=`${cropDraft.w} × ${cropDraft.h}`;for(const k of ['x','y','w','h'])if($(`crop-${k}`))$(`crop-${k}`).value=cropDraft[k];}
function sourcePoint(e){const r=$('image-frame').getBoundingClientRect(),i=active();return {x:Math.round(Math.max(0,Math.min(i.w,(e.clientX-r.left)/r.width*i.w))),y:Math.round(Math.max(0,Math.min(i.h,(e.clientY-r.top)/r.height*i.h)))};}
function resizeCrop(start,p,handle){const i=active();let anchor={x:handle.includes('w')?start.x+start.w:start.x,y:handle.includes('n')?start.y+start.h:start.y};let w=Math.max(1,Math.abs(p.x-anchor.x)),h=Math.max(1,Math.abs(p.y-anchor.y));if(cropRatio){w=Math.min(w,h*cropRatio);h=w/cropRatio;}return {x:Math.round(p.x<anchor.x?anchor.x-w:anchor.x),y:Math.round(p.y<anchor.y?anchor.y-h:anchor.y),w:Math.max(1,Math.round(w)),h:Math.max(1,Math.round(h))};}
$('image-frame').onpointerdown=e=>{if(currentTool!=='crop'||busy||!cropDraft)return;e.preventDefault();const handle=e.target.closest('[data-handle]')?.dataset.handle;gesture={start:sourcePoint(e),crop:clone(cropDraft),mode:handle||($('crop-box').contains(e.target)&&!(cropDraft.w===active().w&&cropDraft.h===active().h)?'move':'new')};$('image-frame').setPointerCapture(e.pointerId);};
$('image-frame').onpointermove=e=>{if(!gesture)return;const i=active(),p=sourcePoint(e),g=gesture;if(g.mode==='move'){cropDraft.x=Math.max(0,Math.min(i.w-g.crop.w,g.crop.x+p.x-g.start.x));cropDraft.y=Math.max(0,Math.min(i.h-g.crop.h,g.crop.y+p.y-g.start.y));}else if(g.mode==='new'){let w=Math.abs(p.x-g.start.x),h=Math.abs(p.y-g.start.y);if(cropRatio){w=Math.min(w,h*cropRatio);h=w/cropRatio;}cropDraft={x:Math.round(p.x<g.start.x?g.start.x-w:g.start.x),y:Math.round(p.y<g.start.y?g.start.y-h:g.start.y),w:Math.max(1,Math.round(w)),h:Math.max(1,Math.round(h))};}else{cropDraft=resizeCrop(g.crop,p,g.mode);cropDraft.w=Math.min(cropDraft.w,i.w-cropDraft.x);cropDraft.h=Math.min(cropDraft.h,i.h-cropDraft.y);}drawCrop();};
$('image-frame').onpointerup=$('image-frame').onpointercancel=()=>gesture=null;
for(const h of document.querySelectorAll('[data-handle]'))h.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)||!cropDraft)return;e.preventDefault();const step=e.shiftKey?10:1,handle=h.dataset.handle,c=clone(cropDraft),x=handle.includes('w')?c.x:c.x+c.w,y=handle.includes('n')?c.y:c.y+c.h;const p={x:Math.max(0,Math.min(active().w,x+(e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0))),y:Math.max(0,Math.min(active().h,y+(e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0)))};cropDraft=resizeCrop(c,p,handle);drawCrop();};

async function processItems(list){if(busy||!list.length)return;if(currentTool==='crop'&&cropDraft&&list.includes(active())){const i=active(),next={...i.settings,crop:clone(cropDraft)};try{outputDimensions(i,next);}catch(e){notice(e.message);return;}const before=clone(i.settings);i.settings=next;historyPush(i,before);discard(i);currentTool='convert';cropDraft=null;}busy=true;previewVersion++;clearZip();panel(false);lockUI();notice('');$('progress').hidden=false;$('progress').max=list.length;$('progress').value=0;let ok=0;try{for(let n=0;n<list.length;n++){const i=list[n];discard(i);i.processing=true;renderThumbs();lockUI();status(`${n+1}/${list.length} 처리 중 · ${i.file.name}`);await new Promise(r=>setTimeout(r,20));try{const r=await renderImage(i);const ext=i.settings.mime.split('/')[1].replace('jpeg','jpg');const base=i.file.name.replace(/\.[^.]+$/,'').replace(/[\\/:*?"<>|]/g,'_');i.result={...r,url:URL.createObjectURL(r.blob),name:`${base}-flick-${items.indexOf(i)+1}.${ext}`};ok++;}catch(e){i.error=e.message;}i.processing=false;$('progress').value=n+1;}}finally{busy=false;$('progress').hidden=true;refresh();panel(true);status(`처리 완료 · 성공 ${ok}장 / 실패 ${list.length-ok}장${ok?' · 결과를 다운로드하세요.':''}`);if(active()?.error)notice(active().error);}}
async function makeZip(){if(busy)return;const ready=selected().filter(i=>i.result);if(!ready.length){notice('선택한 이미지부터 처리해 주세요.');return;}busy=true;clearZip();lockUI();status('ZIP 파일을 만드는 중입니다…');try{const files=[];for(const i of ready)files.push({name:i.result.name,data:new Uint8Array(await i.result.blob.arrayBuffer())});const blob=zip(files);zipUrl=URL.createObjectURL(blob);$('zip-download').href=zipUrl;$('zip-download').download='FLiCK-Photo.zip';$('zip-download').hidden=false;status(`${ready.length}장 ZIP 준비 완료 · 하단 ‘ZIP 저장’을 눌러주세요.`);}catch{notice('ZIP 생성에 실패했습니다. 이미지 수를 줄이거나 개별 다운로드를 이용하세요.');}finally{busy=false;lockUI();}}
for(const [name,title] of tools){const b=el('button',undefined,'tool-button');b.dataset.tool=name;b.append(icon(name),el('span',title));b.onclick=()=>setTool(name);$('tool-nav').append(b);}
document.querySelectorAll('[data-upload]').forEach(b=>b.onclick=()=>{if(!busy)$('files').click();});$('files').onchange=e=>addFiles(e.target.files);$('try-demo').onclick=demo;
document.querySelectorAll('[data-start-tool]').forEach(b=>b.onclick=()=>{pendingTool=b.dataset.startTool;if(items.length){showStudio();setTool(pendingTool);pendingTool=null;}else $('files').click();});
$('home').onclick=showHome;$('return-studio').onclick=showStudio;$('dismiss-notice').onclick=()=>notice('');$('undo').onclick=()=>undo();$('redo').onclick=()=>undo(true);$('reset').onclick=reset;
$('close-panel').onclick=()=>panel(false);$('toggle-panel').onclick=()=>panel(!$('studio').classList.contains('panel-open'));
$('process').onclick=()=>processItems([active()]);$('top-export').onclick=()=>processItems([active()]);$('batch-process').onclick=()=>processItems(selected());$('make-zip').onclick=makeZip;
$('select-all').onclick=()=>{const all=items.every(i=>i.selected);items.forEach(i=>i.selected=!all);clearZip();renderThumbs();if(currentTool==='batch')renderSettings();lockUI();};$('remove-selected').onclick=()=>removeItems(selected());
$('view-compare').onclick=()=>{comparing=true;schedulePreview();};$('view-edit').onclick=()=>{comparing=false;schedulePreview();};$('compare').oninput=updateCompare;
$('zoom-in').onclick=()=>{fitMode=false;zoom=Math.min(3,zoom*1.25);scaleFrame();};$('zoom-out').onclick=()=>{fitMode=false;zoom=Math.max(.005,zoom/1.25);scaleFrame();};$('fit').onclick=()=>{fitMode=true;fit();};new ResizeObserver(()=>{if(fitMode&&active())fit();}).observe($('viewport'));
let dragDepth=0;window.addEventListener('dragenter',e=>{if(!e.dataTransfer?.types.includes('Files'))return;e.preventDefault();dragDepth++;$('dropzone').classList.add('drag');});window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;$('dropzone').classList.remove('drag');}});window.addEventListener('drop',e=>{e.preventDefault();dragDepth=0;$('dropzone').classList.remove('drag');if(e.dataTransfer?.files.length)addFiles(e.dataTransfer.files);});
document.addEventListener('keydown',e=>{if($('studio').hidden)return;const editing=e.target.matches('input,select,textarea,[contenteditable=true]');if(!editing&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);}if(e.key==='Escape')panel(false);});
